∀ {κ : Type u_4} {ι : Type u_5} {H : Type u_6} {inst : Fintype ι} {inst_1 : NormedAddCommGroup H}
  {inst_2 : InnerProductSpace ℂ H} {inst_3 : CompleteSpace H} {hamiltonian : H →L[ℂ] H}
  {hamiltonian_selfAdjoint : IsSelfAdjoint hamiltonian} {eigenbasis : OrthonormalBasis ι ℂ H} {energy : ι → ℝ}
  {hamiltonian_eigenvector : ∀ (n : ι), hamiltonian (eigenbasis n) = ↑(energy n) • eigenbasis n}
  {hamiltonianDerivative : κ → H →L[ℂ] H} {eigenvectorDerivative : κ → ι → H} {energyDerivative : κ → ι → ℝ}
  {differentiatedEigenpair :
    ∀ (μ : κ) (n : ι),
      (hamiltonianDerivative μ) (eigenbasis n) + hamiltonian (eigenvectorDerivative μ n) =
        ↑(energyDerivative μ n) • eigenbasis n + ↑(energy n) • eigenvectorDerivative μ n}
  {differentiatedOrthonormality :
    ∀ (μ : κ) (m n : ι),
      inner ℂ (eigenvectorDerivative μ m) (eigenbasis n) + inner ℂ (eigenbasis m) (eigenvectorDerivative μ n) = 0}
  {hamiltonian_1 : H →L[ℂ] H} {hamiltonian_selfAdjoint_1 : IsSelfAdjoint hamiltonian_1}
  {eigenbasis_1 : OrthonormalBasis ι ℂ H} {energy_1 : ι → ℝ}
  {hamiltonian_eigenvector_1 : ∀ (n : ι), hamiltonian_1 (eigenbasis_1 n) = ↑(energy_1 n) • eigenbasis_1 n}
  {hamiltonianDerivative_1 : κ → H →L[ℂ] H} {eigenvectorDerivative_1 : κ → ι → H} {energyDerivative_1 : κ → ι → ℝ}
  {differentiatedEigenpair_1 :
    ∀ (μ : κ) (n : ι),
      (hamiltonianDerivative_1 μ) (eigenbasis_1 n) + hamiltonian_1 (eigenvectorDerivative_1 μ n) =
        ↑(energyDerivative_1 μ n) • eigenbasis_1 n + ↑(energy_1 n) • eigenvectorDerivative_1 μ n}
  {differentiatedOrthonormality_1 :
    ∀ (μ : κ) (m n : ι),
      inner ℂ (eigenvectorDerivative_1 μ m) (eigenbasis_1 n) + inner ℂ (eigenbasis_1 m) (eigenvectorDerivative_1 μ n) =
        0},
  { hamiltonian := hamiltonian, hamiltonian_selfAdjoint := hamiltonian_selfAdjoint, eigenbasis := eigenbasis,
        energy := energy, hamiltonian_eigenvector := hamiltonian_eigenvector,
        hamiltonianDerivative := hamiltonianDerivative, eigenvectorDerivative := eigenvectorDerivative,
        energyDerivative := energyDerivative, differentiatedEigenpair := differentiatedEigenpair,
        differentiatedOrthonormality := differentiatedOrthonormality } =
      { hamiltonian := hamiltonian_1, hamiltonian_selfAdjoint := hamiltonian_selfAdjoint_1, eigenbasis := eigenbasis_1,
        energy := energy_1, hamiltonian_eigenvector := hamiltonian_eigenvector_1,
        hamiltonianDerivative := hamiltonianDerivative_1, eigenvectorDerivative := eigenvectorDerivative_1,
        energyDerivative := energyDerivative_1, differentiatedEigenpair := differentiatedEigenpair_1,
        differentiatedOrthonormality := differentiatedOrthonormality_1 } →
    hamiltonian = hamiltonian_1 ∧
      eigenbasis = eigenbasis_1 ∧
        energy = energy_1 ∧
          hamiltonianDerivative = hamiltonianDerivative_1 ∧
            eigenvectorDerivative = eigenvectorDerivative_1 ∧ energyDerivative = energyDerivative_1

