∀ {α : Type u} {inst : DecidableEq α} {Object ConnectedObject : Finset α → Type v}
  {fintypeObject : (S : Finset α) → Fintype (Object S)}
  {fintypeConnectedObject : (S : Finset α) → Fintype (ConnectedObject S)}
  {decompose : (S : Finset α) → Object S ≃ (π : Finpartition S) × ((B : ↥π.parts) → ConnectedObject ↑B)}
  {Object_1 ConnectedObject_1 : Finset α → Type v} {fintypeObject_1 : (S : Finset α) → Fintype (Object_1 S)}
  {fintypeConnectedObject_1 : (S : Finset α) → Fintype (ConnectedObject_1 S)}
  {decompose_1 : (S : Finset α) → Object_1 S ≃ (π : Finpartition S) × ((B : ↥π.parts) → ConnectedObject_1 ↑B)},
  { Object := Object, ConnectedObject := ConnectedObject, fintypeObject := fintypeObject,
        fintypeConnectedObject := fintypeConnectedObject, decompose := decompose } =
      { Object := Object_1, ConnectedObject := ConnectedObject_1, fintypeObject := fintypeObject_1,
        fintypeConnectedObject := fintypeConnectedObject_1, decompose := decompose_1 } →
    Object = Object_1 ∧
      ConnectedObject = ConnectedObject_1 ∧
        fintypeObject ≍ fintypeObject_1 ∧ fintypeConnectedObject ≍ fintypeConnectedObject_1 ∧ decompose ≍ decompose_1

