  {connectedWeight : {S : Finset α} → D.ConnectedObject S → R}
  {weight_decompose :
    ∀ {S : Finset α} (d : D.Object S), objectWeight d = ∏ B, connectedWeight (((D.decompose S) d).snd B)}
  {objectWeight_1 : {S : Finset α} → D.Object S → R} {connectedWeight_1 : {S : Finset α} → D.ConnectedObject S → R}
  {weight_decompose_1 :
