∀ {n : ℕ} (pairing : Combinatorics.Pairing n),
  pairing.pairEndpointEquiv =
    { toFun := pairing.pairEndpoint,
      invFun := fun i =>
        if h : i < pairing.partner i then (⟨(i, pairing.partner i), ⋯⟩, 0) else (⟨(pairing.partner i, i), ⋯⟩, 1),
      left_inv := ⋯, right_inv := ⋯ }

