∀ {𝕜 : Type u_1} {Test : Type u_2} {OneForm : Type u_3} {Obs : Type u_4} {inst : CommSemiring 𝕜}
  {inst_1 : AddCommMonoid Test} {inst_2 : _root_.Module 𝕜 Test} {inst_3 : AddCommMonoid OneForm}
  {inst_4 : _root_.Module 𝕜 OneForm} {inst_5 : AddCommMonoid Obs} {inst_6 : _root_.Module 𝕜 Obs} {δ : Obs →ₗ[𝕜] Obs}
  {Q : Test →ₗ[𝕜] Obs} {d : Test →ₗ[𝕜] OneForm} {current : OneForm →ₗ[𝕜] Obs} {source : Test →ₗ[𝕜] Obs}
  {balance : ∀ (f : Test), δ (Q f) = current (d f) + source f} {current_1 : OneForm →ₗ[𝕜] Obs}
  {source_1 : Test →ₗ[𝕜] Obs} {balance_1 : ∀ (f : Test), δ (Q f) = current_1 (d f) + source_1 f},
  { current := current, source := source, balance := balance } =
      { current := current_1, source := source_1, balance := balance_1 } →
    current = current_1 ∧ source = source_1

