  {occupation occupationDerivative surfacePrimitive surfacePrimitiveDerivative seaKernel : ℝ → ℂ}
  {occupation_continuous : ContinuousOn occupation (Set.uIcc lowerEnergy upperEnergy)}
  {surfacePrimitive_continuous : ContinuousOn surfacePrimitive (Set.uIcc lowerEnergy upperEnergy)}
  {occupation_hasDerivAt :
    ∀ energy ∈ Set.Ioo (min lowerEnergy upperEnergy) (max lowerEnergy upperEnergy),
      HasDerivAt occupation (occupationDerivative energy) energy}
  {surfacePrimitive_hasDerivAt :
    ∀ energy ∈ Set.Ioo (min lowerEnergy upperEnergy) (max lowerEnergy upperEnergy),
      HasDerivAt surfacePrimitive (surfacePrimitiveDerivative energy) energy}
  {occupationDerivative_intervalIntegrable :
    IntervalIntegrable occupationDerivative MeasureTheory.volume lowerEnergy upperEnergy}
  {surfacePrimitiveDerivative_intervalIntegrable :
    IntervalIntegrable surfacePrimitiveDerivative MeasureTheory.volume lowerEnergy upperEnergy}
  {seaProduct_intervalIntegrable :
    IntervalIntegrable (fun energy => occupation energy * seaKernel energy) MeasureTheory.volume lowerEnergy
      upperEnergy}
  {boundary_vanishes :
    occupation upperEnergy * surfacePrimitive upperEnergy - occupation lowerEnergy * surfacePrimitive lowerEnergy = 0}
  {lowerEnergy_1 upperEnergy_1 : ℝ}
  {occupation_1 occupationDerivative_1 surfacePrimitive_1 surfacePrimitiveDerivative_1 seaKernel_1 : ℝ → ℂ}
  {occupation_continuous_1 : ContinuousOn occupation_1 (Set.uIcc lowerEnergy_1 upperEnergy_1)}
  {surfacePrimitive_continuous_1 : ContinuousOn surfacePrimitive_1 (Set.uIcc lowerEnergy_1 upperEnergy_1)}
  {occupation_hasDerivAt_1 :
    ∀ energy ∈ Set.Ioo (min lowerEnergy_1 upperEnergy_1) (max lowerEnergy_1 upperEnergy_1),
      HasDerivAt occupation_1 (occupationDerivative_1 energy) energy}
  {surfacePrimitive_hasDerivAt_1 :
    ∀ energy ∈ Set.Ioo (min lowerEnergy_1 upperEnergy_1) (max lowerEnergy_1 upperEnergy_1),
      HasDerivAt surfacePrimitive_1 (surfacePrimitiveDerivative_1 energy) energy}
  {occupationDerivative_intervalIntegrable_1 :
    IntervalIntegrable occupationDerivative_1 MeasureTheory.volume lowerEnergy_1 upperEnergy_1}
  {surfacePrimitiveDerivative_intervalIntegrable_1 :
    IntervalIntegrable surfacePrimitiveDerivative_1 MeasureTheory.volume lowerEnergy_1 upperEnergy_1}
  {seaProduct_intervalIntegrable_1 :
    IntervalIntegrable (fun energy => occupation_1 energy * seaKernel_1 energy) MeasureTheory.volume lowerEnergy_1
      upperEnergy_1}
  {boundary_vanishes_1 :
    occupation_1 upperEnergy_1 * surfacePrimitive_1 upperEnergy_1 -
        occupation_1 lowerEnergy_1 * surfacePrimitive_1 lowerEnergy_1 =
      0},
  { lowerEnergy := lowerEnergy, upperEnergy := upperEnergy, occupation := occupation,
        occupationDerivative := occupationDerivative, surfacePrimitive := surfacePrimitive,
        surfacePrimitiveDerivative := surfacePrimitiveDerivative, seaKernel := seaKernel,
        occupation_continuous := occupation_continuous, surfacePrimitive_continuous := surfacePrimitive_continuous,
        occupation_hasDerivAt := occupation_hasDerivAt, surfacePrimitive_hasDerivAt := surfacePrimitive_hasDerivAt,
        occupationDerivative_intervalIntegrable := occupationDerivative_intervalIntegrable,
        surfacePrimitiveDerivative_intervalIntegrable := surfacePrimitiveDerivative_intervalIntegrable,
        seaProduct_intervalIntegrable := seaProduct_intervalIntegrable, boundary_vanishes := boundary_vanishes } =
      { lowerEnergy := lowerEnergy_1, upperEnergy := upperEnergy_1, occupation := occupation_1,
        occupationDerivative := occupationDerivative_1, surfacePrimitive := surfacePrimitive_1,
        surfacePrimitiveDerivative := surfacePrimitiveDerivative_1, seaKernel := seaKernel_1,
        occupation_continuous := occupation_continuous_1, surfacePrimitive_continuous := surfacePrimitive_continuous_1,
        occupation_hasDerivAt := occupation_hasDerivAt_1, surfacePrimitive_hasDerivAt := surfacePrimitive_hasDerivAt_1,
        occupationDerivative_intervalIntegrable := occupationDerivative_intervalIntegrable_1,
        surfacePrimitiveDerivative_intervalIntegrable := surfacePrimitiveDerivative_intervalIntegrable_1,
        seaProduct_intervalIntegrable := seaProduct_intervalIntegrable_1, boundary_vanishes := boundary_vanishes_1 } →
    lowerEnergy = lowerEnergy_1 ∧
      upperEnergy = upperEnergy_1 ∧
        occupation = occupation_1 ∧
          occupationDerivative = occupationDerivative_1 ∧
            surfacePrimitive = surfacePrimitive_1 ∧
              surfacePrimitiveDerivative = surfacePrimitiveDerivative_1 ∧ seaKernel = seaKernel_1

